{"issue": true, "summary": "The 'map' method on the returned generator function incorrectly uses 'this' which is not bound to the generator, causing a TypeError when calling Array.from with the iterable.", "edits": [{"path": "index.js", "old": "			async value(iterable, function_) {
				const promises = Array.from(iterable, (value, index) => this(function_, value, index));
				return Promise.all(promises);
			},", "new": "			async value(iterable, function_) {
				const promises = Array.from(iterable, (value, index) => generator(function_, value, index));
				return Promise.all(promises);
			},"}]}
